    // Moslashtirish / xarita savoli: javob — bitta harf, variantlar guruhda.
    private static ObjQuestion Pick711(int n, string prompt, string answer, string explanation) =>
        new(n, prompt, null, [answer], explanation);

    private const string FormTwoWords711 = "Complete the form below.\nWrite NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer.";
    private const string NotesOneWordNumber711 = "Complete the notes below.\nWrite ONE WORD AND/OR A NUMBER for each answer.";
    private const string NotesTwoWordsNumber711 = "Complete the notes below.\nWrite NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer.";
