            [
                Mcq(21, "Why did the students choose to study the testing effect?", ["It was the easiest topic available.", "It was relevant to their own studying.", "It had not been studied before."], "B",
                    "\"The honest reason is that it's useful to us ... it should change the way we revise.\""),
